{"tool": "writeProjectFile", "params": {"content": "import { AttackerProfile } from './profile';
import { writeFileSync, readFileSync, renameSync, existsSync } from 'fs';

export class ProfileStore {
  private nextSeqCounter = 0;
  private lastAppliedSeqCounter = 0;

  constructor(private logPath: string, private snapshotPath: string) {}

  snapshot(profiles: AttackerProfile[]) {
    const payload = {
      schema: 2,
      nextSeq: this.nextSeqCounter,
      lastAppliedSeq: this.lastAppliedSeqCounter,
      profiles
    };
    const tmp = `${this.snapshotPath}.tmp`;
    writeFileSync(tmp, JSON.stringify(payload));
    renameSync(tmp, this.snapshotPath);
  }

  load(): AttackerProfile[] {
    if (!existsSync(this.snapshotPath)) return [];

    const raw = readFileSync(this.snapshotPath, 'utf8');
    let parsed: { schema?: number; nextSeq?: number; lastAppliedSeq?: number; profiles?: AttackerProfile[] };
    try {
      parsed = JSON.parse(raw);
    } catch { return []; }

    if (parsed.schema === 2) {
      this.setCounters(parsed.nextSeq ?? 0, parsed.lastAppliedSeq ?? 0);
      return parsed.profiles ?? [];
    }

    // Legacy v1 support
    return (parsed as any).profiles ?? [];
  }

  apply(mutation: any) {
    this.nextSeqCounter++;
    mutation.seq = this.nextSeqCounter;
  }

  mutate(profiles: AttackerProfile[], mutation: any) {
    if (mutation.seq !== undefined && mutation.seq > this.lastAppliedSeqCounter) {
      this.lastAppliedSeqCounter = mutation.seq;
    }
    // apply logic...
  }

  replayLogGate(m: any): boolean {
    return m.seq === undefined || m.seq > this.lastAppliedSeqCounter;
  }

  setCounters(next: number, last: number) {
    this.nextSeqCounter = next;
    this.lastAppliedSeqCounter = last;
  }

  get nextSeq() { return this.nextSeqCounter; }
  get lastAppliedSeq() { return this.lastAppliedSeqCounter; }
}", "path": "src/ai/hunt-mode/profile-store.ts"}}
